SELECT



    sb.deleted = 0

        AND ri.instance_code = CONCAT('ROOM_', #{dto.roomId})


        AND sb.status = #{dto.resStatus}


        AND sb.start_time >= #{dto.startTime}


        AND sb.end_time <= #{dto.endTime}


ORDER BY sb.create_time DESC

SELECT



    sb.deleted = 0
    AND sb.user_id = #{userId}

        AND ri.instance_code = CONCAT('ROOM_', #{dto.roomId})


        AND sb.status = #{dto.resStatus}


        AND sb.start_time >= #{dto.startTime}


        AND sb.end_time <= #{dto.endTime}


ORDER BY sb.create_time DESC
